import math

def euler_phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

# We need to calculate phi(2013)
print(euler_phi(2013))

def is_permutation_poly_mod_3(a3, a1):
    # P(x) = a3*x^3 + a1*x
    # Modulo 3, since x^3 = x mod 3, P(x) = (a3 + a1) * x mod 3

    A = (a3 + a1) % 3

    # P(x) is a PP mod 3 if and only if A is non-zero mod 3.
    return A != 0

valid_count = 0
# a3 must be in {1, 2}
for a3 in [1, 2]:
    # a1 must be in {0, 1, 2}
    for a1 in [0, 1, 2]:
        if is_permutation_poly_mod_3(a3, a1):
            print(f"({a3}, {a1}) is valid")
            valid_count += 1

print(f"Total count: {valid_count}")
